mapper.select:
SELECT 
FROM tb_mdm_variant t
WHERE t.row_valid = 1

    AND t.id = #{id}


    AND t.code = #{code}


    AND t.name = #{name}


    AND t.name_local = #{nameLocal}


    AND t.model_code = #{modelCode}


    AND t.source = #{source}


    AND t.external_ref_id = #{externalRefId}


    AND t.external_version = #{externalVersion}


    AND t.description = #{description}


    AND t.create_time = #{createTime}


    AND t.create_by = #{createBy}


    AND t.modify_time = #{modifyTime}


    AND t.modify_by = #{modifyBy}


    AND t.row_version = #{rowVersion}

ORDER BY t.id DESC

SELECT 

WHERE v.row_valid = 1

    AND v.model_code = #{modelCode}


    AND m.car_line_code = #{carLineCode}


    AND m.platform_code = #{platformCode}


    AND v.code = #{code}


    AND (v.name LIKE #{name} OR v.name_local LIKE #{name})


    and date_format(v.create_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')


    and date_format(v.create_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')

ORDER BY v.id DESC

